5: import type { AudienceFit, Campaign } from "@/lib/contract";
6: import { campaignAffectsHeatmap, getCampaignLocation } from "@/lib/campaign-location";
7: 
8: type Position = [number, number];
9: 
10: export type TractShapes = {
11:   type: "FeatureCollection";
12:   features: {
13:     type: "Feature";
14:     properties: { geoid: string; borough: string; neighborhood?: string };
15:     geometry:
16:       | { type: "Polygon"; coordinates: Position[][] }
17:       | { type: "MultiPolygon"; coordinates: Position[][][] };
18:   }[];
19: };
20: 
21: export type LayerId = "gap" | "fit" | "competition";
22: 
23: /** Per tract, each layer's value from 0 to 1. */
24: export type TractLayers = Record<string, Record<LayerId, number>>;
25: 
26: export function recommendationLayer(campaigns: Campaign[]): "gap" | "fit" {
27:   return campaigns.some(campaignAffectsHeatmap) ? "gap" : "fit";
28: }
29: 
30: /** A campaign's reach falls to about a third at this distance from its matched location. */
31: const CAMPAIGN_REACH_KM = 1;
32: 
33: /** Mean of the outer ring's vertices; close enough to the centre for tract-sized shapes. */
34: function centre(geometry: TractShapes["features"][number]["geometry"]): Position {
35:   const ring = geometry.type === "Polygon" ? geometry.coordinates[0] : geometry.coordinates[0][0];
36:   let x = 0;
37:   let y = 0;
38:   for (const [lng, lat] of ring) {
39:     x += lng;
40:     y += lat;
41:   }
42:   return [x / ring.length, y / ring.length];
43: }
44: 
45: function distanceKm([lng1, lat1]: Position, [lng2, lat2]: Position) {
46:   const kmPerDegLat = 111.2;
47:   const kmPerDegLng = kmPerDegLat * Math.cos(((lat1 + lat2) / 2) * (Math.PI / 180));
48:   return Math.hypot((lng1 - lng2) * kmPerDegLng, (lat1 - lat2) * kmPerDegLat);
49: }
50: 
51: export function computeLayers(
52:   shapes: TractShapes,
53:   fit: AudienceFit,
54:   campaigns: Campaign[],
55: ): TractLayers {
56:   const locations: Position[] = campaigns.flatMap((campaign) => {
57:     const location = getCampaignLocation(campaign);
58:     return campaignAffectsHeatmap(campaign) && location ? [[location.longitude, location.latitude] as Position] : [];
59:   });
60:   const layers: TractLayers = {};
61:   for (const feature of shapes.features) {
62:     const { geoid } = feature.properties;
63:     const audience = fit.scores[geoid];
64:     if (audience === undefined) continue;
65:     const here = centre(feature.geometry);
66:     let competition = 0;
67:     for (const s of locations) {
68:       const d = distanceKm(here, s) / CAMPAIGN_REACH_KM;
69:       competition = Math.max(competition, Math.exp(-d * d));
70:     }
71:     layers[geoid] = {
72:       fit: audience,
73:       competition,
74:       gap: audience * (1 - competition),
75:     };
76:   }
77:   return layers;
78: }
79: 
80: export function strongest(layers: TractLayers, layer: LayerId, n: number) {
81:   return Object.entries(layers)
82:     .sort((a, b) => b[1][layer] - a[1][layer])
83:     .slice(0, n)
84:     .map(([geoid]) => geoid);
85: }

